import pandas as pd, numpy as np
from scipy.optimize import curve_fit
def L(x,a,x0,w,c0,c1): return a*(w/2)**2/((x-x0)**2+(w/2)**2)+c0+c1*(x-x0)
def PV(x,a,x0,w,eta,c0,c1):
    g=np.exp(-4*np.log(2)*(x-x0)**2/w**2); l=(w/2)**2/((x-x0)**2+(w/2)**2)
    return a*(eta*l+(1-eta)*g)+c0+c1*(x-x0)
res={}
for f in ['0.5','2','5']:
    d=pd.read_csv(f'spectrum_{f}mW.csv'); x=d.shift_cm1.values;y=d.intensity.values
    for name,lo,hi,p0 in [('G',1500,1680,[y[(x>1570)&(x<1590)].max(),1580,14,y[(x>1500)&(x<1520)].mean(),0]),('2D',2520,2840,[y[(x>2650)&(x<2680)].max(),2667,28,y[(x>2520)&(x<2540)].mean(),0])]:
        s=(x>lo)&(x<hi)
        p,c=curve_fit(L,x[s],y[s],p0=p0); e=np.sqrt(np.diag(c))
        q,cq=curve_fit(PV,x[s],y[s],p0=[p[0],p[1],p[2],0.8,p[3],p[4]],bounds=([0,lo,1,0,-1e5,-100],[1e6,hi,200,1,1e6,100]))
        r=y[s]-L(x[s],*p)
        print(f,name,'Lor pos %.2f+-%.2f fwhm %.2f+-%.2f h %.0f'%(p[1],e[1],p[2],e[2],p[0]),'| pV pos %.2f fwhm %.2f eta %.2f'%(q[1],q[2],q[3]),'resid rms/h %.3f'%(r.std()/p[0]))
E

